import{_ as t}from"./chunks/cc-switch-import-token.Bz2JgHsb.js";import{_ as e,o as i,c,a5 as s}from"./chunks/framework.C1a7WKBV.js";const l="/ai-handbook/assets/tutorials/cc-switch-release-assets.png",o="/ai-handbook/assets/tutorials/cc-switch-download-installer.png",r="/ai-handbook/assets/tutorials/cc-switch-settings.png",h="/ai-handbook/assets/tutorials/cc-switch-general-options.png",d="/ai-handbook/assets/tutorials/cc-switch-advanced-options.png",n="/ai-handbook/assets/tutorials/cc-switch-codex-routing.png",f=JSON.parse('{"title":"CC Switch 对接 STJAPI","description":"安装 CC Switch，并从 STJAPI 控制台导入令牌。","frontmatter":{"title":"CC Switch 对接 STJAPI","description":"安装 CC Switch，并从 STJAPI 控制台导入令牌。"},"headers":[],"relativePath":"clients/cc-switch.md","filePath":"clients/cc-switch.md","lastUpdated":1788838685000}'),p={name:"clients/cc-switch.md"};function C(_,a,u,S,w,m){return i(),c("div",null,[...a[0]||(a[0]=[s('<h1 id="cc-switch-对接-stjapi" tabindex="-1">CC Switch 对接 STJAPI <a class="header-anchor" href="#cc-switch-对接-stjapi" aria-label="Permalink to &quot;CC Switch 对接 STJAPI&quot;">​</a></h1><p>CC Switch 用于管理 Claude、Codex、Gemini 等客户端的服务配置。本页以 STJAPI 为例，说明下载、基础设置和令牌导入流程。</p><h2 id="_1-准备工作" tabindex="-1">1. 准备工作 <a class="header-anchor" href="#_1-准备工作" aria-label="Permalink to &quot;1. 准备工作&quot;">​</a></h2><h3 id="_1-1-安装-claude-code" tabindex="-1">1.1 安装 Claude Code <a class="header-anchor" href="#_1-1-安装-claude-code" aria-label="Permalink to &quot;1.1 安装 Claude Code&quot;">​</a></h3><p>请先完成 <a href="/clients/claude-code">Claude Code 全平台安装</a>。CC Switch 用于管理配置，CLI 本体仍需要独立安装。</p><h3 id="_1-2-准备-stjapi-令牌" tabindex="-1">1.2 准备 STJAPI 令牌 <a class="header-anchor" href="#_1-2-准备-stjapi-令牌" aria-label="Permalink to &quot;1.2 准备 STJAPI 令牌&quot;">​</a></h3><p>登录 <a href="https://ai.stjapi.com/" target="_blank" rel="noreferrer">STJAPI 控制台</a>，创建令牌时确认分组无误。令牌创建后可直接导入 CC Switch。</p><h2 id="_2-下载-cc-switch" tabindex="-1">2. 下载 CC Switch <a class="header-anchor" href="#_2-下载-cc-switch" aria-label="Permalink to &quot;2. 下载 CC Switch&quot;">​</a></h2><p>从 <a href="https://github.com/farion1231/cc-switch/releases" target="_blank" rel="noreferrer">CC Switch Releases</a> 下载对应系统版本。</p><ul><li>Windows：先点击 <code>Show all assets</code> 展开完整列表，再选择 MSI 安装包。</li><li>macOS、Linux：选择和处理器架构相符的安装包。</li><li>列表中通常同时有绿色便携版和安装程序；日常使用推荐安装程序。</li></ul><p><img src="'+l+'" alt="在 Releases 页面展开全部安装包"></p><p><img src="'+o+'" alt="选择 Windows 安装程序的示例"></p><h2 id="_3-设置-cc-switch" tabindex="-1">3. 设置 CC Switch <a class="header-anchor" href="#_3-设置-cc-switch" aria-label="Permalink to &quot;3. 设置 CC Switch&quot;">​</a></h2><h3 id="_3-1-打开设置" tabindex="-1">3.1 打开设置 <a class="header-anchor" href="#_3-1-打开设置" aria-label="Permalink to &quot;3.1 打开设置&quot;">​</a></h3><p>启动 CC Switch 后，点击左上角的设置图标。</p><p><img src="'+r+'" alt="CC Switch 设置入口"></p><h3 id="_3-2-通用选项" tabindex="-1">3.2 通用选项 <a class="header-anchor" href="#_3-2-通用选项" aria-label="Permalink to &quot;3.2 通用选项&quot;">​</a></h3><p>在通用选项中下拉查看开关。按当前客户端和使用习惯启用推荐选项，保存后再进行供应商配置。</p><p><img src="'+h+'" alt="CC Switch 通用选项"></p><h3 id="_3-3-高级选项" tabindex="-1">3.3 高级选项 <a class="header-anchor" href="#_3-3-高级选项" aria-label="Permalink to &quot;3.3 高级选项&quot;">​</a></h3><p>高级选项中需要设置本机 Claude 相关配置文件夹。使用默认路径时先确认它指向当前正在使用的 Claude 配置目录。</p><p><img src="'+d+'" alt="CC Switch 高级选项"></p><h2 id="_4-添加-stjapi-供应商" tabindex="-1">4. 添加 STJAPI 供应商 <a class="header-anchor" href="#_4-添加-stjapi-供应商" aria-label="Permalink to &quot;4. 添加 STJAPI 供应商&quot;">​</a></h2><h3 id="_4-1-从控制台导入" tabindex="-1">4.1 从控制台导入 <a class="header-anchor" href="#_4-1-从控制台导入" aria-label="Permalink to &quot;4.1 从控制台导入&quot;">​</a></h3><p>回到 STJAPI 的令牌列表，点击目标令牌旁的“导入到 CCS”。CC Switch 中出现新增配置后，检查服务地址、令牌名称、分组和启用状态；如果列表中已有同名配置，优先更新已有项，避免误用旧令牌。</p><p><img src="'+t+'" alt="从 STJAPI 令牌列表导入到 CCS"></p><h3 id="_4-2-codex-使用-gpt-模型时" tabindex="-1">4.2 Codex 使用 GPT 模型时 <a class="header-anchor" href="#_4-2-codex-使用-gpt-模型时" aria-label="Permalink to &quot;4.2 Codex 使用 GPT 模型时&quot;">​</a></h3><p>当 Codex 使用 GPT 模型时，不需要开启路由。保存配置后，在 CC Switch 中选择对应供应商并启用。</p><p><img src="'+n+'" alt="Codex 使用 GPT 模型时的路由设置"></p><h2 id="_5-验证连接" tabindex="-1">5. 验证连接 <a class="header-anchor" href="#_5-验证连接" aria-label="Permalink to &quot;5. 验证连接&quot;">​</a></h2><ol><li>在 CC Switch 中启用刚导入的配置。</li><li>打开终端，执行 <code>claude</code> 或 <code>codex</code>。</li><li>发送一个简单任务，例如“解释当前目录的文件结构”。</li><li>在 STJAPI 控制台确认令牌出现使用记录。</li></ol><p>连接失败时按以下顺序检查：</p><ol><li><a href="/getting-started/stjapi#连接异常">STJAPI 账户与网络设置</a> 中的网络和直连规则。</li><li>CC Switch 当前启用的配置，确认不是同名旧配置。</li><li>令牌分组、服务地址和模型是否匹配。</li><li>STJAPI 控制台是否有新的使用记录。</li></ol>',33)])])}const T=e(p,[["render",C]]);export{f as __pageData,T as default};
